271:   font-size: 0.9rem;
272:   color: var(--dark-brown);
273: }
274: 
275: /* --------------------------------------------------------------------------
276:    4. Featured Recipes Filter Bar & Recipe Cards
277:    -------------------------------------------------------------------------- */
278: .filter-bar {
279:   display: flex;
280:   flex-wrap: wrap;
281:   gap: 0.5rem;
282:   margin-bottom: 0.75rem;
283: }
284: 
285: .filter-btn {
286:   padding: 0.45rem 0.95rem;
287:   border: 1.5px solid var(--sage-green);
288:   border-radius: 999px;
289:   background-color: transparent;
290:   color: var(--forest-green);
291:   font-family: var(--font-body);
292:   font-size: 0.9rem;
293:   font-weight: 600;
294:   cursor: pointer;
295:   transition:
296:     background-color var(--transition-fast),
297:     border-color var(--transition-fast),
298:     color var(--transition-fast);
